import{_ as a,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Agrupar eventos relacionados","description":"","frontmatter":{"title":"Agrupar eventos relacionados","id":"eproc-agrupar-eventos-relacionados","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.1.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-agrupar-eventos-relacionados"}]]},"headers":[],"relativePath":"funcionalidades/eproc-agrupar-eventos-relacionados.md","filePath":"funcionalidades/eproc-agrupar-eventos-relacionados.md"}'),n={name:"funcionalidades/eproc-agrupar-eventos-relacionados.md"};function i(t,e,d,c,l,m){return o(),s("div",null,e[0]||(e[0]=[r('<h1 id="agrupar-eventos-relacionados" tabindex="-1">Agrupar eventos relacionados <a class="header-anchor" href="#agrupar-eventos-relacionados" aria-label="Permalink to &quot;Agrupar eventos relacionados&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Deixa a tabela de eventos mais curta e legível, reunindo eventos que formam uma coisa só: intimações expedidas em lote, eventos que apontam para o mesmo documento e eventos que só confirmam ou complementam o anterior. Também sinaliza quando o mesmo documento aparece em eventos distantes.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, tabela de eventos.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p>Não é preciso fazer nada: a tabela já aparece agrupada. O que muda:</p><ul><li><strong>Eventos repetidos de um mesmo comando</strong> (por exemplo, uma intimação para cada destinatário) viram uma linha-resumo expansível, com o intervalo de eventos, a data e o usuário. Clique na linha para ver cada evento, com o destinatário e o prazo de cada um.</li><li><strong>Eventos seguidos com o mesmo documento</strong> viram uma linha só, com as descrições em lista e um único link para o documento.</li><li><strong>Eventos que se confirmam ou se complementam</strong> (por exemplo, &quot;Expedida/certificada a intimação eletrônica&quot; e &quot;Confirmada a intimação eletrônica&quot;, expedição e recebimento de mandado, publicação no DJEN, remessa e recebimento de autos, ou uma decisão &quot;Complementar ao evento nº X&quot;) são recolhidos juntos na mesma linha-resumo.</li><li><strong>Mesmo documento em eventos distantes</strong>: um pequeno ícone colorido aparece ao lado de cada ocorrência. Passe o mouse para destacar, nessa cor, todas as linhas onde o documento aparece. Clique para ir até a outra ocorrência.</li><li><strong>Processos migrados do PJe</strong>: eventos do mesmo ID no PJe lançados no mesmo instante são reunidos (veja <a href="./eproc-ajustar-eventos-migrados-pje">Ajustar eventos de processos migrados do PJe</a>), e as &quot;certidões de erro de migração&quot; em sequência ficam recolhidas numa linha cinza.</li></ul><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções neste card. As opções de mesclagem de eventos migrados do PJe ficam em <a href="./eproc-ajustar-eventos-migrados-pje">Ajustar eventos de processos migrados do PJe (TJMG)</a>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Nenhum evento é apagado: as linhas originais só ficam ocultas e reaparecem ao expandir o grupo ou ao desligar o recurso.</li><li>Os pares de eventos reconhecidos são uma lista fixa. Pares que não estão nela continuam separados.</li><li>Eventos de &quot;mesmo documento à distância&quot; não são movidos, só sinalizados.</li></ul>',12)]))}const h=a(n,[["render",i]]);export{p as __pageData,h as default};
